      [ANNOTATE]: [
        'from measure_vessels import (segment, prune, umpp_for,',
        '                             ARTERY_DIAM_PX, SRC)',
        '',
        "SCALEBAR_PX = {'fig1': 61, 'fig3': 47, 'fig4': 76}",
